#include "chronus1/emulator.h"
#include "chronus1/isa.h"
#include <cmath>
#include <cstring>
#include <filesystem>
#include <iostream>
#include <vector>
using namespace chronus1;
static void require(bool v,const char*m){if(!v)throw std::runtime_error(m);}template<class F>static void traps(F f,TrapCode c){try{f();throw std::runtime_error("expected trap");}catch(const Trap&t){require(t.code==c,"wrong trap");}}
static Binary bin(std::vector<uint32_t> code,uint32_t mem=1024){Binary b; b.major=1;b.minor=1;b.global_bytes=mem;b.code=std::move(code);return b;}
static float flt(uint32_t v){float x;std::memcpy(&x,&v,4);return x;}
static void test_decode(){std::vector<Opcode> ops={Opcode::NOP,Opcode::MOV,Opcode::MOVI,Opcode::ADD,Opcode::SUB,Opcode::MUL,Opcode::FMA,Opcode::LOAD,Opcode::STORE,Opcode::LLOAD,Opcode::LSTORE,Opcode::BARRIER,Opcode::BRA,Opcode::BRAZ,Opcode::BRANZ,Opcode::GET_GID,Opcode::GET_LID,Opcode::GET_GSIZE,Opcode::GET_LSIZE,Opcode::EXIT};for(auto o:ops){uint32_t raw;if(o==Opcode::MOVI||o==Opcode::LOAD||o==Opcode::LLOAD)raw=encode_i(o,1,o==Opcode::MOVI?0:2,3);else if(o==Opcode::STORE||o==Opcode::LSTORE)raw=encode_i(o,1,2,3);else if(o==Opcode::BRA||o==Opcode::BRAZ||o==Opcode::BRANZ)raw=encode_b(o,o==Opcode::BRA?0:1,0);else if(o==Opcode::BARRIER)raw=encode_s(o,1,0);else if(o==Opcode::GET_GID||o==Opcode::GET_LID||o==Opcode::GET_GSIZE||o==Opcode::GET_LSIZE)raw=encode_s(o,1,2);else if(o==Opcode::NOP||o==Opcode::EXIT)raw=encode_r(o);else raw=encode_r(o,1,o==Opcode::MOV?2:1,(o==Opcode::ADD||o==Opcode::SUB||o==Opcode::MUL||o==Opcode::FMA)?2:0,o==Opcode::FMA?3:0);require(decode(raw).op==o,"decode mismatch");}traps([]{decode(7u<<26);},TrapCode::IllegalOpcode);traps([]{decode(encode_r(Opcode::NOP,1));},TrapCode::MalformedEncoding);traps([]{decode(encode_s(Opcode::BARRIER,4,0));},TrapCode::InvalidSelector);traps([]{decode(encode_s(Opcode::GET_GID,1,3));},TrapCode::InvalidSelector);}
static void test_add_store(){auto b=bin({encode_i(Opcode::MOVI,1,0,2),encode_i(Opcode::MOVI,2,0,2),encode_r(Opcode::ADD,3,1,2),encode_i(Opcode::STORE,3,0,0),encode_r(Opcode::EXIT)});auto path=std::filesystem::temp_directory_path()/"chronus1-add.chronus";write_binary(path,b);auto loaded=load_binary(path);std::filesystem::remove(path);Emulator e(loaded,1024);e.dispatch({});require(e.global_memory().read32(0)==4,"2+2 store failed");}
static void test_traps(){traps([]{Emulator e(bin({encode_i(Opcode::LOAD,1,0,2),encode_r(Opcode::EXIT)}),1024);e.dispatch({});},TrapCode::Misaligned);traps([]{Emulator e(bin({encode_i(Opcode::MOVI,1,0,1020),encode_i(Opcode::LOAD,2,1,8),encode_r(Opcode::EXIT)}),1024);e.dispatch({});},TrapCode::OutOfBounds);traps([]{Emulator e(bin({encode_b(Opcode::BRA,0,-1)}),1024);Dispatch d;d.instruction_budget=8;e.dispatch(d);},TrapCode::BudgetExhausted);traps([]{std::vector<uint32_t> c={encode_s(Opcode::GET_LID,1,0),encode_b(Opcode::BRAZ,1,1),encode_s(Opcode::BARRIER,1,0),encode_r(Opcode::EXIT)};auto b=bin(c);b.reconvergence={{4,12}};Emulator e(b,1024);Dispatch d;d.global={2,1,1};d.local={2,1,1};e.dispatch(d);},TrapCode::InvalidEarlyExit);}
static void test_divergence(){std::vector<uint32_t> c={encode_s(Opcode::GET_LID,1,0),encode_b(Opcode::BRAZ,1,2),encode_i(Opcode::MOVI,2,0,1),encode_b(Opcode::BRA,0,1),encode_i(Opcode::MOVI,2,0,2),encode_i(Opcode::MOVI,3,0,4),encode_r(Opcode::MUL,4,1,3),encode_i(Opcode::STORE,2,4,0),encode_r(Opcode::EXIT)};auto b=bin(c);b.reconvergence={{4,20}};Emulator e(b,1024);Dispatch d;d.global={4,1,1};d.local={4,1,1};e.dispatch(d);require(e.global_memory().read32(0)==2,"taken path failed");for(int i=1;i<4;i++)require(e.global_memory().read32(i*4)==1,"fallthrough path failed");}
static void test_partial_barrier(){std::vector<uint32_t> c={encode_s(Opcode::GET_GID,1,0),encode_i(Opcode::MOVI,2,0,4),encode_r(Opcode::MUL,3,1,2),encode_s(Opcode::BARRIER,1,0),encode_i(Opcode::STORE,1,3,0),encode_r(Opcode::EXIT)};Emulator e(bin(c,4096),4096);Dispatch d;d.global={35,1,1};d.local={32,1,1};e.dispatch(d);for(int i=0;i<35;i++)require(e.global_memory().read32(i*4)==uint32_t(i),"partial barrier result failed");}
static std::vector<uint32_t> matmul(){std::vector<uint32_t>c;auto R=[&](Opcode o,int d=0,int a=0,int b=0,int x=0){c.push_back(encode_r(o,d,a,b,x));};auto I=[&](Opcode o,int d,int a,int v){c.push_back(encode_i(o,d,a,v));};auto S=[&](Opcode o,int d,int x){c.push_back(encode_s(o,d,x));};S(Opcode::GET_GID,1,0);S(Opcode::GET_GID,2,1);S(Opcode::GET_LID,3,0);S(Opcode::GET_LID,4,1);I(Opcode::MOVI,5,0,2);I(Opcode::MOVI,6,0,4);I(Opcode::MOVI,7,0,64);I(Opcode::MOVI,8,0,128);I(Opcode::MOVI,14,0,1);R(Opcode::MUL,10,4,5);R(Opcode::ADD,10,10,3);R(Opcode::MUL,10,10,6);R(Opcode::MUL,11,2,5);R(Opcode::ADD,11,11,1);R(Opcode::MUL,11,11,6);I(Opcode::LOAD,12,11,0);I(Opcode::LSTORE,12,10,0);R(Opcode::ADD,11,11,7);I(Opcode::LOAD,12,11,0);I(Opcode::LSTORE,12,10,32);S(Opcode::BARRIER,1,0);I(Opcode::MOVI,9,0,0);I(Opcode::MOVI,13,0,0);I(Opcode::MOVI,15,0,2);int loop=c.size();R(Opcode::MUL,16,4,5);R(Opcode::ADD,16,16,13);R(Opcode::MUL,16,16,6);I(Opcode::LLOAD,17,16,0);R(Opcode::MUL,18,13,5);R(Opcode::ADD,18,18,3);R(Opcode::MUL,18,18,6);I(Opcode::LLOAD,19,18,32);R(Opcode::FMA,9,17,19,9);R(Opcode::ADD,13,13,14);R(Opcode::SUB,15,15,14);c.push_back(encode_b(Opcode::BRANZ,15,loop-int(c.size())-1));R(Opcode::MUL,20,2,5);R(Opcode::ADD,20,20,1);R(Opcode::MUL,20,20,6);R(Opcode::ADD,20,20,8);I(Opcode::STORE,9,20,0);R(Opcode::EXIT);return c;}
static void test_matmul_replay(){auto run=[](){Emulator e(bin(matmul(),256),256);float a[4]={1,2,3,4},b[4]={5,6,7,8};e.global_memory().write_bytes(0,a,sizeof a);e.global_memory().write_bytes(64,b,sizeof b);Dispatch d;d.global={2,2,1};d.local={2,2,1};e.dispatch(d);std::vector<uint32_t>o;for(int i=0;i<4;i++)o.push_back(e.global_memory().read32(128+i*4));return o;};auto x=run();for(int replay=0;replay<99;replay++)require(x==run(),"replay not bit exact");float expected[4]={19,22,43,50};for(int i=0;i<4;i++)require(std::fabs(flt(x[i])-expected[i])<1e-6f,"matmul mismatch");}


static void test_hostile_barriers(){
 // Different static barrier instances cannot release each other.
 traps([]{std::vector<uint32_t>c={encode_s(Opcode::GET_LID,1,0),encode_b(Opcode::BRAZ,1,1),encode_s(Opcode::BARRIER,1,0),encode_s(Opcode::BARRIER,1,0),encode_r(Opcode::EXIT)};auto b=bin(c);b.reconvergence={{4,16}};Emulator e(b,1024);Dispatch d;d.global={2,1,1};d.local={2,1,1};e.dispatch(d);},TrapCode::BarrierDeadlock);
 // A legal barrier loop remains subject to the global instruction budget.
 traps([]{std::vector<uint32_t>c={encode_s(Opcode::BARRIER,1,0),encode_b(Opcode::BRA,0,-2)};Emulator e(bin(c),1024);Dispatch d;d.global={4,1,1};d.local={4,1,1};d.instruction_budget=20;e.dispatch(d);},TrapCode::BudgetExhausted);
 // Local writes before a fenced barrier are visible after release.
 std::vector<uint32_t>c={encode_s(Opcode::GET_LID,1,0),encode_i(Opcode::MOVI,2,0,4),encode_r(Opcode::MUL,3,1,2),encode_i(Opcode::MOVI,4,0,9),encode_i(Opcode::LSTORE,4,3,0),encode_s(Opcode::BARRIER,1,0),encode_i(Opcode::LLOAD,5,3,0),encode_i(Opcode::STORE,5,3,0),encode_r(Opcode::EXIT)};Emulator e(bin(c),1024);Dispatch d;d.global={4,1,1};d.local={4,1,1};e.dispatch(d);for(int i=0;i<4;i++)require(e.global_memory().read32(i*4)==9,"barrier local fence failed");
}

static void test_architecture_edges(){
 std::vector<uint32_t> c={encode_r(Opcode::NOP),encode_i(Opcode::MOVI,1,0,-1),encode_i(Opcode::MOVI,2,0,1),encode_r(Opcode::ADD,3,1,2),encode_i(Opcode::MOVI,7,0,123),encode_r(Opcode::MOV,31,7),encode_i(Opcode::MOVI,0,0,7),encode_s(Opcode::GET_GSIZE,4,0),encode_s(Opcode::GET_LSIZE,5,0),encode_i(Opcode::MOVI,6,0,200),encode_i(Opcode::STORE,3,6,0),encode_i(Opcode::STORE,0,6,4),encode_i(Opcode::STORE,31,6,8),encode_i(Opcode::STORE,4,6,12),encode_i(Opcode::STORE,5,6,16),encode_r(Opcode::EXIT)};
 Emulator e(bin(c),1024);Dispatch d;d.global={7,1,1};d.local={7,1,1};e.dispatch(d);require(e.global_memory().read32(200)==0,"integer wrap failed");require(e.global_memory().read32(204)==0,"R0 changed");require(e.global_memory().read32(208)==123,"R31/SP alias failed");require(e.global_memory().read32(212)==7&&e.global_memory().read32(216)==7,"size selectors failed");
}
static void test_fma_fused(){
 std::vector<uint32_t> c={encode_i(Opcode::LOAD,1,0,0),encode_i(Opcode::LOAD,2,0,4),encode_i(Opcode::LOAD,3,0,8),encode_r(Opcode::FMA,4,1,2,3),encode_i(Opcode::STORE,4,0,12),encode_r(Opcode::EXIT)};Emulator e(bin(c),1024);
 float a=0x1.000002p+0f,b=0x1.fffffep-1f,cx=-1.0f;uint32_t av,bv,cv;std::memcpy(&av,&a,4);std::memcpy(&bv,&b,4);std::memcpy(&cv,&cx,4);e.global_memory().write32(0,av);e.global_memory().write32(4,bv);e.global_memory().write32(8,cv);e.dispatch({});float fused=std::fma(a,b,cx);volatile float product=a*b;float split=product+cx;uint32_t fv,sv;std::memcpy(&fv,&fused,4);std::memcpy(&sv,&split,4);require(fv!=sv,"FMA discriminator is not discriminating");require(e.global_memory().read32(12)==fv,"FMA was not fused");
}
static void test_local_isolation(){
 std::vector<uint32_t> c={encode_i(Opcode::LLOAD,1,0,0),encode_s(Opcode::GET_GID,2,0),encode_i(Opcode::MOVI,3,0,4),encode_r(Opcode::MUL,4,2,3),encode_i(Opcode::STORE,1,4,0),encode_i(Opcode::MOVI,5,0,99),encode_i(Opcode::LSTORE,5,0,0),encode_r(Opcode::EXIT)};Emulator e(bin(c),1024);Dispatch d;d.global={2,1,1};d.local={1,1,1};e.dispatch(d);require(e.global_memory().read32(0)==0&&e.global_memory().read32(4)==0,"local memory leaked between groups");
}
static void test_address_wrap(){traps([]{std::vector<uint32_t>c={encode_i(Opcode::MOVI,1,0,-4),encode_i(Opcode::LOAD,2,1,8),encode_r(Opcode::EXIT)};Emulator e(bin(c),1024);e.dispatch({});},TrapCode::OutOfBounds);}
static void test_divergence_overflow(){Warp w;for(int i=0;i<32;i++)w.push_divergence({uint32_t(i*4),uint32_t(i*4+4),1,2});traps([&]{w.push_divergence({128,132,1,2});},TrapCode::DivergenceOverflow);}
static void test_decoder_fuzz(){uint32_t x=0x12345678u;uint64_t accepted=0,trapped=0;for(int i=0;i<1000000;i++){x^=x<<13;x^=x>>17;x^=x<<5;try{(void)decode(x);accepted++;}catch(const Trap&){trapped++;}}require(accepted>0&&trapped>0&&accepted+trapped==1000000,"decoder fuzz accounting failed");}
static void test_vector_add(){
 std::vector<uint32_t>c={encode_s(Opcode::GET_GID,1,0),encode_i(Opcode::MOVI,2,0,4),encode_r(Opcode::MUL,3,1,2),encode_i(Opcode::LOAD,4,3,0),encode_i(Opcode::MOVI,5,0,64),encode_r(Opcode::ADD,6,3,5),encode_i(Opcode::LOAD,7,6,0),encode_r(Opcode::ADD,8,4,7),encode_i(Opcode::MOVI,9,0,128),encode_r(Opcode::ADD,10,3,9),encode_i(Opcode::STORE,8,10,0),encode_r(Opcode::EXIT)};Emulator e(bin(c,256),256);for(int i=0;i<8;i++){e.global_memory().write32(i*4,i);e.global_memory().write32(64+i*4,10+i);}Dispatch d;d.global={8,1,1};d.local={8,1,1};e.dispatch(d);for(int i=0;i<8;i++)require(e.global_memory().read32(128+i*4)==uint32_t(10+2*i),"vector add failed");
}
static void test_local_reduction(){
 std::vector<uint32_t>c={encode_s(Opcode::GET_LID,1,0),encode_i(Opcode::MOVI,2,0,4),encode_r(Opcode::MUL,3,1,2),encode_i(Opcode::MOVI,4,0,1),encode_r(Opcode::ADD,4,4,1),encode_i(Opcode::LSTORE,4,3,0),encode_s(Opcode::BARRIER,1,0),encode_i(Opcode::LLOAD,5,0,0),encode_i(Opcode::LLOAD,6,0,4),encode_i(Opcode::LLOAD,7,0,8),encode_i(Opcode::LLOAD,8,0,12),encode_r(Opcode::ADD,9,5,6),encode_r(Opcode::ADD,9,9,7),encode_r(Opcode::ADD,9,9,8),encode_i(Opcode::STORE,9,0,0),encode_r(Opcode::EXIT)};Emulator e(bin(c),1024);Dispatch d;d.global={4,1,1};d.local={4,1,1};e.dispatch(d);require(e.global_memory().read32(0)==10,"local reduction failed");
}

int main(){try{test_decode();test_add_store();test_traps();test_divergence();test_partial_barrier();test_hostile_barriers();test_matmul_replay();test_architecture_edges();test_fma_fused();test_local_isolation();test_address_wrap();test_divergence_overflow();test_decoder_fuzz();test_vector_add();test_local_reduction();std::cout<<"Chronus-1 emulator acceptance: PASS\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
